import { useEffect } from "react";
import interactionsIifeUrl from "@pantoken/interactions/interactions.iife.js?url";

// Client-only: the interactions bundle touches `document` at import time, unavailable during SSR.
// A resolved asset URL + a real <script> tag, not import() — a dynamic import() of a pure
// side-effect module from a "sideEffects": false package can get tree-shaken out of a production
// bundle since nothing is imported *from* it.
export function PantokenInteractions() {
  useEffect(() => {
    const script = document.createElement("script");
    script.src = interactionsIifeUrl;
    document.head.append(script);
    return () => script.remove();
  }, []);
  return null;
}
"}

