const previewFrame = document.querySelector("#preview");
const contentEl = document.querySelector(".content");
function resizePreviewFrame() {
  const root = previewFrame.contentDocument?.documentElement;
  console.log("resize measure scrollHeight=", root && root.scrollHeight);
  if (root) previewFrame.style.height = root.scrollHeight + "px";
}
previewFrame.addEventListener("load", () => {
  resizePreviewFrame();
  const root = previewFrame.contentDocument?.documentElement;
  if (root) new ResizeObserver(resizePreviewFrame).observe(root);
});
