document.querySelector("#toggle").addEventListener("click", () => {
  contentEl.style.flexDirection = contentEl.style.flexDirection === "row" ? "column" : "row";
  console.log("toggled to", contentEl.style.flexDirection, "iframe height now", previewFrame.style.height, previewFrame.getBoundingClientRect().height);
});
</script>
</body>
</html>
